Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "set">set</param>
/// <param name = "_AVACostModelCombination">_AVACostModelCombination</param>
/// <returns>AVACostModelCombination</returns>
public  edit AVACostModelCombination editAVACostModelCombination(
    boolean                       set,
    AVACostModelCombination       _AVACostModelCombination
    )
{
    calcJobObsVar.observe();

    if (set)
    {
        AVABomCalcParameter::setAVACostModelCombination(_AVACostModelCombination);
    }

    return calcJob.parmAVACostModelCombination();
}

/// <summary>
/// designed from AVA
/// </summary>
/// <returns>boolean</returns>
boolean modifiedVersionId()
{
    boolean     ret;
    CostingVersion  costingVersion = CostingVersion::find(calcJob.parmVersionId());

    ret = next modifiedVersionId();

    AVABomCalcParameter::setAVACostModelCombination(costingVersion.AVACostModelCombination);
    if (costingVersion.AVAUseStandardCalcQty)
    {
        this.itemQty(true,costingVersion.AVAStandardCalculateQty);
    }
    return ret;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_costingVersion">_costingVersion</param>
void enableVersionRecordingFields(CostingVersion _costingVersion)
{
    next enableVersionRecordingFields(_costingVersion);
    calcDate.enabled(true);
}
